import { edit_presence_visitors } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    visitorEdition: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      VisitorName: ""
    };
  },
  watch: {
    visitorEdition: {
      async handler() {
        if (this.visitorEdition == true) {
          this.VisitorName = this.rowInfo.visitor_name;
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_Entity() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(edit_presence_visitors, {
            input: {
              visitor_id: this.rowInfo.visitor_id,
              visitor_name: this.VisitorName
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.edit_presence_visitors);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    }
  }
};
